1	@import "tailwindcss";
2	@import "tw-animate-css";
3	@import "@fontsource-variable/geist";
4	
5	@custom-variant dark (&:is(.dark *));
6	
7	@theme {
8	  --color-brand-50: #fde8eb;
9	  --color-brand-100: #f9c5cd;
10	  --color-brand-200: #f48e9f;
11	  --color-brand-300: #ef5771;
12	  --color-brand-400: #e94560;
13	  --color-brand-500: #d91a3a;
14	  --color-brand-600: #b0152e;
15	  --color-brand-700: #871022;
16	  --color-brand-800: #5e0b17;
17	  --color-brand-900: #35060c;
18	  --color-brand: #e94560;
19	
20	  --color-cyan-50: #ccfaff;
21	  --color-cyan-100: #99f5ff;
22	  --color-cyan-200: #4deeff;
23	  --color-cyan-300: #00e5ff;
24	  --color-cyan-400: #00d9ff;
25	  --color-cyan-500: #00b8d9;
26	  --color-cyan-600: #0097b3;
27	  --color-cyan-700: #00758c;
28	  --color-cyan-800: #005466;
29	  --color-cyan-900: #003240;
30	  --color-cyan: #00d9ff;
31	
32	  --font-sans: "Geist Variable", sans-serif;
33	  --font-display: "Geist Variable", sans-serif;
34	}
35	
36	@keyframes fadeInUp { from { opacity: 0; transform: translateY(30px); } to { opacity: 1; transform: translateY(0); } }
37	@keyframes float { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-10px); } }
38	@keyframes kenburns { 0% { transform: scale(1); } 100% { transform: scale(1.1); } }
39	@keyframes mobileNavIn { from { opacity: 0; transform: translateY(-8px); } to { opacity: 1; transform: translateY(0); } }
40	@keyframes mobileNavBackdrop { from { opacity: 0; } to { opacity: 1; } }
41	@keyframes pulse-soft { 0%, 100% { opacity: 0.6; } 50% { opacity: 1; } }
42	@keyframes modalIn { from { opacity: 0; transform: scale(0.95) translateY(10px); } to { opacity: 1; transform: scale(1) translateY(0); } }
43	@keyframes modalBackdrop { from { opacity: 0; } to { opacity: 1; } }
44	@keyframes certSlideIn { from { transform: translateY(40px) scale(0.95); opacity: 0; } to { transform: translateY(0) scale(1); opacity: 1; } }
45	@keyframes certBackdropIn { from { opacity: 0; } to { opacity: 1; } }
46	@keyframes blink { 50% { opacity: 0; } }
47	
48	:root, [data-theme="dark"] {
49	  --hover-subtle: rgba(255,255,255,0.05);
50	  --bg-primary: #0a0a0a;
51	  --bg-secondary: #111;
52	  --bg-card: #0d0d1a;
53	  --bg-surface: #0d0d0d;
54	  --nav-bg: rgba(10,10,10,0.7);
55	  --text-primary: #eaeaea;
56	  --text-secondary: #ccc;
57	  --text-tertiary: #aaa;
58	  --text-muted: #888;
59	  --text-subtle: #555;
60	  --text-faint: #666;
61	  --border-color: #222;
62	  --border-light: #333;
63	  --badge-bg: #222;
64	  --nav-border: rgba(255,255,255,0.05);
65	  --modal-bg: #111;
66	  --modal-border: #333;
67	  --section-glow-1: #0f0a1a;
68	  --section-glow-2: #0a0a1a;
69	  --section-glow-3: #0f0a0a;
70	}
71	
72	[data-theme="light"] {
73	  --hover-subtle: rgba(0,0,0,0.05);
74	  --bg-primary: #ffffff;
75	  --bg-secondary: #f5f5f5;
76	  --bg-card: #f0f0fa;
77	  --bg-surface: #fafafa;
78	  --nav-bg: rgba(255,255,255,0.8);
79	  --text-primary: #1a1a1a;
80	  --text-secondary: #333;
81	  --text-tertiary: #555;
82	  --text-muted: #777;
83	  --text-subtle: #999;
84	  --text-faint: #aaa;
85	  --border-color: #e0e0e0;
86	  --border-light: #ddd;
87	  --badge-bg: #eee;
88	  --nav-border: rgba(0,0,0,0.08);
89	  --modal-bg: #f5f5f5;
90	  --modal-border: #ddd;
91	  --section-glow-1: #f5edff;
92	  --section-glow-2: #edf3ff;
93	  --section-glow-3: #fff0ed;
94	}
95	
96	body {
97	  background: var(--bg-primary);
98	  color: var(--text-primary);
99	  font-family: "Geist Variable", sans-serif;
100	  transition: background 0.3s ease, color 0.3s ease;
101	}
102	
103	::selection { background: #e94560; color: #fff; }
104	html { scroll-behavior: smooth; }
105	
106	/* Utility classes */
107	.bg-primary { background: var(--bg-primary); }
108	.bg-secondary { background: var(--bg-secondary); }
109	.hover-subtle:hover { background: var(--hover-subtle); }
110	.bg-card { background: var(--bg-card); }
111	.bg-surface { background: var(--bg-surface); }
112	.bg-badge { background: var(--badge-bg); }
113	.nav-bg { background: var(--nav-bg); }
114	.text-primary { color: var(--text-primary); }
115	.text-secondary { color: var(--text-secondary); }
116	.text-tertiary { color: var(--text-tertiary); }
117	.text-muted { color: var(--text-muted); }
118	.text-subtle { color: var(--text-subtle); }
119	.text-faint { color: var(--text-faint); }
120	.border-custom { border-color: var(--border-color); }
121	.border-light { border-color: var(--border-light); }
122	
123	.card-bg { background: linear-gradient(135deg, var(--bg-secondary), var(--bg-card)); }
124	.section-bg-1 { background: linear-gradient(to bottom, var(--bg-primary), var(--section-glow-1), var(--bg-primary)); }
125	.section-bg-2 { background: linear-gradient(to bottom, var(--bg-primary), var(--section-glow-2), var(--bg-primary)); }
126	.section-bg-3 { background: linear-gradient(to bottom, var(--bg-primary), var(--section-glow-3), var(--bg-primary)); }
127	
128	.gradient-text {
129	  background: linear-gradient(135deg, #e94560, #00d9ff);
130	  -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-clip: text;
131	}
132	
133	.glow { box-shadow: 0 0 30px rgba(233, 69, 96, 0.3); }
134	.glow-cyan { box-shadow: 0 0 30px rgba(0, 217, 255, 0.2); }
135	.hover-glow:hover { box-shadow: 0 0 25px rgba(233, 69, 96, 0.5); transform: translateY(-2px); }
136	.nav-blur { backdrop-filter: blur(16px); -webkit-backdrop-filter: blur(16px); }
137	
138	/* Badge */
139	.badge {
140	  display: inline-flex; align-items: center; gap: 6px;
141	  padding: 4px 12px; border-radius: 9999px;
142	  font-size: 11px; font-weight: 600; letter-spacing: 0.02em;
143	}
144	
145	/* Timeline */
146	.timeline-dot {
147	  width: 14px; height: 14px; border-radius: 50%;
148	  border: 3px solid #e94560; background: var(--bg-primary);
149	  flex-shrink: 0; position: relative; z-index: 1;
150	}
151	.timeline-line {
152	  position: absolute; top: 20px; left: 6px;
153	  width: 2px; height: calc(100% + 24px);
154	  background: linear-gradient(to bottom, #e94560, #00d9ff);
155	}
156	.exp-card { transition: all 0.3s ease; }
157	.exp-card:hover { transform: translateX(8px); }
158	
159	/* Project card */
160	.project-card { transition: all 0.3s ease; border: 1px solid transparent; }
161	.project-card:hover { border-color: #e94560; transform: translateY(-8px); box-shadow: 0 20px 40px rgba(0,0,0,0.4); }
162	
163	/* Tech icon */
164	.icon-tech { width: 40px; height: 40px; transition: all 0.3s ease; opacity: 0.8; }
165	.icon-tech:hover { opacity: 1; transform: scale(1.2) rotate(5deg); }
166	
167	/* Tech popup */
168	.tech-popup {
169	  position: fixed; z-index: 100;
170	  padding: 0.75rem 1rem; border-radius: 0.75rem;
171	  background: var(--bg-secondary); border: 1px solid var(--border-light);
172	  font-size: 0.8rem; color: var(--text-tertiary); line-height: 1.5;
173	  max-width: 300px; pointer-events: none;
174	  opacity: 0; transition: all 0.25s ease;
175	  transform: translateY(8px);
176	  box-shadow: 0 10px 40px rgba(0,0,0,0.5);
177	}
178	.tech-popup.show { opacity: 1; transform: translateY(0); }
179	.tech-popup .tp-label { color: #00d9ff; font-weight: 600; }
180	
181	/* Slideshow */
182	.bg-slideshow { position: absolute; inset: 0; z-index: 0; overflow: hidden; cursor: grab; user-select: none; }
183	.bg-slideshow:active { cursor: grabbing; }
184	.bg-slide {
185	  position: absolute; inset: 0;
186	  background-size: cover; background-position: center;
187	  opacity: 0; transition: opacity 1.5s ease;
188	  pointer-events: none;
189	}
190	.bg-slide.active { opacity: 1; }
191	.bg-slide.kenburns { animation: kenburns 10s ease forwards; }
192	
193	.slide-nav {
194	  position: absolute; top: 50%; z-index: 5; transform: translateY(-50%);
195	  width: 48px; height: 48px; border-radius: 50%;
196	  background: rgba(0,0,0,0.4); border: 1px solid rgba(255,255,255,0.1);
197	  color: #888; cursor: pointer; display: flex; align-items: center; justify-content: center;
198	  transition: all 0.3s ease; backdrop-filter: blur(4px);
199	}
200	.slide-nav:hover { background: rgba(233,69,96,0.3); color: #fff; border-color: #e94560; }
201	.slide-nav.prev { left: 16px; }
202	.slide-nav.next { right: 16px; }
203	@media (max-width: 640px) { .slide-nav { display: none; } }
204	
205	/* Section reveal */
206	.section-in {
207	  opacity: 0; transform: translateY(40px);
208	  transition: opacity 0.8s ease, transform 0.8s ease;
209	}
210	.section-in.visible { opacity: 1; transform: translateY(0); }
211	
212	.stagger-child {
213	  opacity: 0; transform: translateY(30px);
214	  transition: opacity 0.6s ease, transform 0.6s ease;
215	}
216	.section-in.visible .stagger-child { opacity: 1; transform: translateY(0); }
217	.section-in.visible .stagger-child:nth-child(1) { transition-delay: 0s; }
218	.section-in.visible .stagger-child:nth-child(2) { transition-delay: 0.1s; }
219	.section-in.visible .stagger-child:nth-child(3) { transition-delay: 0.2s; }
220	.section-in.visible .stagger-child:nth-child(4) { transition-delay: 0.3s; }
221	.section-in.visible .stagger-child:nth-child(5) { transition-delay: 0.4s; }
222	.section-in.visible .stagger-child:nth-child(6) { transition-delay: 0.5s; }
223	.section-in.visible .stagger-child:nth-child(7) { transition-delay: 0.6s; }
224	.section-in.visible .stagger-child:nth-child(8) { transition-delay: 0.7s; }
225	
226	/* Animations */
227	.animate-fade-in-up { animation: fadeInUp 0.8s ease forwards; }
228	.animate-float { animation: float 4s ease-in-out infinite; }
229	.animate-kenburns { animation: kenburns 10s ease forwards; }
230	.animate-pulse-soft { animation: pulse-soft 2s ease-in-out infinite; }
231	.animate-delay-1 { animation-delay: 0.2s; }
232	.animate-delay-2 { animation-delay: 0.4s; }
233	.animate-delay-3 { animation-delay: 0.6s; }
234	.animate-delay-4 { animation-delay: 0.8s; }
235	
236	/* Mobile nav */
237	#mobile-nav-menu.open { display: block; animation: mobileNavIn 0.2s ease forwards; }
238	#mobile-nav-backdrop.open { display: block; animation: mobileNavBackdrop 0.2s ease forwards; }
239	#mobile-nav-toggle.open span:nth-child(1) { transform: translateY(6px) rotate(45deg); }
240	#mobile-nav-toggle.open span:nth-child(2) { opacity: 0; }
241	#mobile-nav-toggle.open span:nth-child(3) { transform: translateY(-6px) rotate(-45deg); }
242	
243	/* Modal */
244	.modal-overlay { display: none; position: fixed; inset: 0; z-index: 999; align-items: center; justify-content: center; padding: 1rem; }
245	.modal-overlay.active { display: flex; }
246	.modal-backdrop { position: absolute; inset: 0; background: rgba(0,0,0,0.7); backdrop-filter: blur(4px); }
247	.modal-container { position: relative; background: var(--modal-bg); border: 1px solid var(--modal-border); border-radius: 1rem; max-width: 42rem; width: 100%; max-height: 90vh; overflow-y: auto; padding: 1.5rem; }
248	.modal-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 1rem; }
249	.modal-close { width: 2rem; height: 2rem; border-radius: 9999px; border: none; background: var(--badge-bg); color: var(--text-muted); font-size: 1.25rem; cursor: pointer; display: flex; align-items: center; justify-content: center; transition: all 0.2s; }
250	.modal-close:hover { background: #e94560; color: #fff; }
251	.modal-image { width: 100%; border-radius: 0.75rem; background: linear-gradient(135deg, var(--bg-card), var(--modal-bg)); min-height: 200px; display: flex; align-items: center; justify-content: center; color: var(--text-subtle); font-size: 0.875rem; }
252	.modal-footer { display: flex; gap: 0.75rem; margin-top: 1.5rem; flex-wrap: wrap; }
253	.modal-overlay.active .modal-container { animation: modalIn 0.25s ease forwards; }
254	.modal-overlay.active .modal-backdrop { animation: modalBackdrop 0.25s ease forwards; }
255	
256	/* Cert overlay */
257	.cert-overlay { display: none; position: fixed; inset: 0; z-index: 1000; align-items: center; justify-content: center; }
258	.cert-overlay.active { display: flex; }
259	.cert-backdrop { position: absolute; inset: 0; background: rgba(0,0,0,0.85); backdrop-filter: blur(8px); }
260	.cert-overlay.active .cert-backdrop { animation: certBackdropIn 0.3s ease forwards; }
261	.cert-content { position: relative; width: 100%; max-width: 520px; max-height: 90vh; overflow-y: auto; z-index: 10; background: var(--modal-bg); border: 1px solid var(--modal-border); border-radius: 1.25rem; padding: 1.5rem; transform: translateY(30px) scale(0.95); opacity: 0; }
262	.cert-overlay.active .cert-content { animation: certSlideIn 0.35s cubic-bezier(0.16, 1, 0.3, 1) forwards; }
263	.cert-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 1.5rem; }
264	.cert-close { width: 2rem; height: 2rem; border-radius: 9999px; border: none; background: var(--badge-bg); color: var(--text-muted); font-size: 1.25rem; cursor: pointer; display: flex; align-items: center; justify-content: center; transition: all 0.2s; }
265	.cert-close:hover { background: #e94560; color: #fff; transform: rotate(90deg); }
266	.cert-body { text-align: left; }
267	.cert-card { background: var(--bg-card); border: 1px solid var(--border-light); border-radius: 0.75rem; padding: 1rem; transition: all 0.2s; }
268	.cert-card:hover { border-color: #00d9ff40; }
269	.cert-bar-track { height: 4px; background: var(--badge-bg); border-radius: 2px; overflow: hidden; }
270	.cert-bar-fill { height: 100%; background: linear-gradient(90deg, #00d9ff, #e94560); border-radius: 2px; transition: width 0.5s ease; }
271	
272	/* Badge tech (original style) */
273	.badge-tech {
274	  display: inline-flex; align-items: center; gap: 4px;
275	  padding: 3px 10px; border-radius: 9999px;
276	  font-size: 11px; font-weight: 600; letter-spacing: 0.02em;
277	  transition: all 0.2s ease; cursor: default;
278	}
279	.badge-tech:hover {
280	  transform: scale(1.05);
281	}
282	
283	/* Dotted background pattern (Figma-like) */
284	.bg-dots {
285	  background-image: radial-gradient(circle, var(--text-muted) 1px, transparent 1px);
286	  background-size: 20px 20px;
287	  opacity: 0.15;
288	  pointer-events: none;
289	}
290	
291	/* Nav blur (for scroll) */
292	#header.inMoved {
293	  background: var(--nav-bg);
294	  backdrop-filter: blur(16px);
295	  -webkit-backdrop-filter: blur(16px);
296	  border-bottom: 1px solid var(--nav-border);
297	}
