1	---
2	import BreadCrumb from "./BreadCrumb.astro";
3	import ButtonPrimary from "./ButtonPrimary.astro";
4	import ButtonSecondary from "./ButtonSecondary.astro";
5	import IconGithub from "./icons/IconGithub.astro";
6	import IconLink from "./icons/IconLink.astro";
7	import { skills } from "../lib/skills.ts";
8	import type { Project } from "../lib/projects.ts";
9	
10	interface Props {
11	  project: Project;
12	}
13	
14	const { project } = Astro.props;
15	
16	function getSkillColor(name: string): string {
17	  const found = skills.find(s => s.name === name);
18	  return found?.color || "#888";
19	}
20	---
21	
22	<article
23	  class="group relative overflow-hidden rounded-2xl transition-all duration-500 hover:scale-[1.03] hover:shadow-2xl hover:shadow-brand/20"
24	  style="background: var(--bg-secondary); border: 1px solid var(--border-color);"
25	>
26	  <!-- Image -->
27	  <div class="relative h-48 overflow-hidden sm:h-56">
28	    {project.image ? (
29	      <img
30	        src={project.image}
31	        alt={project.title}
32	        class="h-full w-full object-cover transition-all duration-700 group-hover:scale-125 group-hover:translate-y-2"
33	        style="transform-origin: center center; will-change: transform;"
34	        loading="lazy"
35	      />
36	    ) : (
37	      <div class="flex h-full items-center justify-center text-sm" style="color: var(--text-muted); background: var(--bg-secondary);">
38	        {project.title}
39	      </div>
40	    )}
41	    <div class="absolute inset-0 bg-gradient-to-t from-black/70 via-black/20 to-transparent opacity-0 transition-opacity duration-500 group-hover:opacity-100"></div>
42	  </div>
43	
44	  <!-- Content -->
45	  <div class="space-y-3 p-5">
46	    <h3 class="text-lg font-bold transition-colors duration-300 group-hover:text-brand flex items-center gap-2" style="color: var(--text-primary);">
47	      {project.title}
48	      {project.private && <span class="text-[10px] font-medium px-2 py-0.5 rounded-full" style="background: rgba(233,69,96,0.15); color: var(--color-brand); border: 1px solid rgba(233,69,96,0.3);">Privado</span>}
49	    </h3>
50	    <p class="line-clamp-3 text-sm leading-relaxed" style="color: var(--text-muted);">
51	      {project.description}
52	    </p>
53	
54	    <!-- Tech badges -->
55	    <div class="flex flex-wrap gap-1.5">
56	      {project.technologies.slice(0, 5).map(tech => (
57	        <BreadCrumb name={tech} color={getSkillColor(tech)} />
58	      ))}
59	      {project.technologies.length > 5 && (
60	        <span class="text-xs" style="color: var(--text-muted);">+{project.technologies.length - 5}</span>
61	      )}
62	    </div>
63	
64	    <!-- Actions -->
65	    <div class="flex items-center gap-3 pt-2">
66	      <ButtonPrimary href={`/ProyectDetail/${project.id}`}>
67	        Ver detalles
68	      </ButtonPrimary>
69	      <a href={project.github} target="_blank" class="rounded-md p-2 transition-all hover:opacity-70" style="color: var(--text-muted);" aria-label="GitHub">
70	        <IconGithub size={20} />
71	      </a>
72	      {project.live && project.live !== project.github && (
73	        <a href={project.live} target="_blank" class="rounded-md p-2 transition-all hover:opacity-70" style="color: var(--text-muted);" aria-label="Live">
74	          <IconLink size={20} />
75	        </a>
76	      )}
77	    </div>
78	  </div>
79	</article>
