1	---
2	import { iconMap } from "./icons/index";
3	import { hexToRgba, hexToBorder } from "../lib/color.ts";
4	import { skills } from "../lib/skills.ts";
5	
6	interface Props {
7	  name: string;
8	  color: string;
9	}
10	
11	const { name, color } = Astro.props;
12	const Icon = iconMap[`Icon${name.replace(/[\s.-]/g, "")}`] || iconMap.IconReact;
13	const skill = skills.find(s => s.name === name);
14	---
15	
16	<span
17	  class="badge-tech"
18	  style="background: {hexToRgba(color, 0.1)}; color: {color}; border: 1px solid {hexToBorder(color)};"
19	  data-skill={name}
20	  data-description={skill?.description || ""}
21	>
22	  {Icon && <Icon size={10} />}
23	  {name}
24	</span>
25	
26	<script>
27	  document.addEventListener("click", (e) => {
28	    const badge = (e.target as HTMLElement).closest(".badge-tech") as HTMLElement | null;
29	    if (!badge) return;
30	
31	    const existing = document.querySelector(".tech-badge-tooltip");
32	    if (existing && (existing as HTMLElement).dataset.skill === badge.dataset.skill) {
33	      existing.remove();
34	      return;
35	    }
36	    existing?.remove();
37	
38	    const desc = badge.dataset.description;
39	    if (!desc) return;
40	
41	    const tooltip = document.createElement("div");
42	    tooltip.className = "tech-badge-tooltip";
43	    tooltip.dataset.skill = badge.dataset.skill || "";
44	    tooltip.textContent = desc;
45	    tooltip.style.cssText = `
46	      position: fixed; z-index: 9999; bottom: 1.5rem; left: 50%; transform: translateX(-50%);
47	      background: var(--bg-secondary, #1a1a2e); color: var(--text-primary, #e0e0e0);
48	      padding: 0.75rem 1.25rem; border-radius: 0.75rem; font-size: 0.8rem;
49	      max-width: 320px; text-align: center; line-height: 1.4;
50	      border: 1px solid var(--border-color, #2a2a4a); box-shadow: 0 8px 32px rgba(0,0,0,0.4);
51	      animation: fadeInUp 0.25s ease-out both;
52	    `;
53	    document.body.appendChild(tooltip);
54	
55	    setTimeout(() => tooltip.remove(), 4000);
56	  });
57	</script>
