1	---
2	import Layout from "../../layouts/Layout.astro";
3	import { projects } from "../../lib/projects.ts";
4	import { skills } from "../../lib/skills.ts";
5	import BreadCrumb from "../../components/BreadCrumb.astro";
6	import DataProyect from "../../components/DataProyect.astro";
7	import ButtonPrimary from "../../components/ButtonPrimary.astro";
8	import ButtonSecondary from "../../components/ButtonSecondary.astro";
9	import IconArrowLeft from "../../components/icons/IconArrowLeft.astro";
